/* =====================================================================
   COMO PUBLICAR UMA ATUALIZAÇÃO PRA TODO MUNDO QUE USA O LINK:
   1. Edite defaultRaridades(), defaultVariantes() ou defaultTipos() abaixo.
   2. Aumente o número de DATA_VERSION em +1.
   3. Suba o arquivo de novo no Netlify/GitHub Pages (mesmo link).
   Quando alguém abrir o link e o navegador dela tiver uma versão menor
   que DATA_VERSION, as listas de Tipo/Variação/Raridade e o conjunto de
   Tipos são atualizados automaticamente — sem apagar o progresso
   (variação marcada / não marcada) que a pessoa já marcou, nem a foto
   que ela subiu pra cada tipo.
   Isso NÃO sincroniza em tempo real entre pessoas (cada uma guarda o
   próprio progresso no próprio celular) — é uma forma de você, como
   dona do link, empurrar mudanças na estrutura pra todo mundo.

   ÍCONES OFICIAIS: cada tipo pode ter um "slug" que aponta pro ícone
   real de fortniteking.com (ex: água = "water"). Isso é só referência
   de imagem (hotlink), não é uma cópia salva no arquivo — se o site
   mudar as URLs ou tirar do ar, o card cai pro emoji automaticamente.
   Se quiser blindar contra isso, é só a pessoa subir uma foto própria
   no card (isso sempre tem prioridade sobre o ícone oficial).
===================================================================== */
const DATA_VERSION = 7;

const STORAGE_KEY = 'elementais_fortnite_v2';
const LISTS_KEY = 'elementais_listas_v2';
const VERSION_KEY = 'elementais_data_version';

const COLOR_PALETTE = ['#9aa5b1','#4fd672','#4c9fe8','#b45ce0','#e8952f','#f2c14e','#e8636b','#37c9c1','#c9a227','#7c8cf8'];
const FALLBACK_COLOR = '#5a6472';
const EMOJI_OPTIONS = ['💧','🌍','🔥','💨','🐟','🦆','👻','😈','👑','✨','⚽','💭','🤘','🗿','7️⃣','💀','🌀','🦇','🕶️','🐔','🇧🇷','🎤','🦙','🍌','🧊','🧩','⭐','🎯','🛡️','🏆','❓'];

/* Nome (minúsculo) -> slug oficial em fortniteking.com/sprites/<slug>_<variação>.png */
const OFFICIAL_SLUGS = {
  'água':'water', 'terra':'earth', 'fogo':'fire', 'ar':'air', 'peixoto':'fishy',
  'pato':'duck', 'fantasma':'ghost', 'demônio':'demon', 'rei':'king', 'aura':'drifter',
  'atacante':'soccer', 'sonho':'dream', 'punk':'punk', 'chefe':'boss', 'seven':'seven',
  'ceifador':'grimreaper', 'ponto zero':'zeropoint', 'batman':'batman', 'john wick':'johnwick',
  'amendoim torrado':'theburntpeanut', 'pollo':'pollo', 'vini jr.':'vinijr', 'ironmouse':'ironmouse',
  'lhama':'llama', 'embananado':'peely'
};
/* Nome da variação -> slug oficial usado na URL do ícone */
const VARIANT_SLUG = {
  'Normal':'basic', 'Dourado':'gold', 'Gelatinoso':'candy', 'Galáctico':'galaxy',
  'Metalizado':'holofoil', 'Cúbico':'cube', 'Quack':'quack', 'Gema':'gem'
};
/* Nome da variação -> cor de destaque do card (nome do card + borda quando marcado) */
const VARIANT_COLORS = {
  'Normal':'#5ee6c8', 'Dourado':'#f2c14e', 'Gelatinoso':'#e85ec8', 'Galáctico':'#9b6ce0',
  'Metalizado':'#c9d2db', 'Cúbico':'#4c9fe8', 'Quack':'#ffb454', 'Gema':'#37c9c1'
};

const TIPO_ORDER = [
  'Água','Terra','Fogo','Pato','Fantasma','Sonho','Demônio','Punk','Rei',
  'Amendoim Torrado','Vini Jr.','Ponto Zero','Peixoto','Atacante','Aura','Chefe',
  'Ceifador','Ar','Seven','Pollo','Lhama','Embananado'
];

let remoteCatalog = null;

const METALIZADO_DISPONIVEIS = new Set([
  'Água','Fogo','Fantasma','Rei','Atacante','Ar','Seven','Batman','Ceifador',
  'Ponto Zero','Embananado'
]);

const CUBICO_DISPONIVEIS = new Set([
  'Terra','Fogo','Peixoto','Punk','Sonho','Chefe','Batman','Ceifador','Ponto Zero'
]);

const QUACK_DISPONIVEIS = new Set([
  'Terra','Fogo','Ponto Zero'
]);

const GEMA_DISPONIVEIS = new Set([
  'Lhama'
]);

function isVariantSoon(t, variante){
  const remoteType = remoteCatalog && remoteCatalog.tipos
    ? remoteCatalog.tipos.find(x => x.nome === t.nome || x.slug === t.slug)
    : null;
  const remoteVariant = remoteType && remoteType.variantes
    ? remoteType.variantes[variante]
    : null;

  if(remoteVariant && typeof remoteVariant.status === 'string'){
    return remoteVariant.status === 'em_breve';
  }

  // Fallback local: mantém o site funcional mesmo se elementais.json falhar.
  if(variante === 'Metalizado') return !METALIZADO_DISPONIVEIS.has(t.nome);
  if(variante === 'Cúbico') return !CUBICO_DISPONIVEIS.has(t.nome);
  if(variante === 'Quack') return !QUACK_DISPONIVEIS.has(t.nome);
  if(variante === 'Gema') return !GEMA_DISPONIVEIS.has(t.nome);
  return false;
}

function tipoOrderRank(nome){
  const i = TIPO_ORDER.indexOf(nome);
  return i === -1 ? 999 : i;
}
function lookupSlug(nome){
  return OFFICIAL_SLUGS[(nome||'').trim().toLowerCase()] || null;
}
function spriteUrl(t, variante){
  if(!t.slug) return null;
  const vs = VARIANT_SLUG[variante];
  if(!vs) return null;
  return `https://www.fortniteking.com/sprites/${t.slug}_${vs}.png`;
}
function getVariantColor(v){ return VARIANT_COLORS[v] || FALLBACK_COLOR; }

function genericSilhouetteHtml(){
  return `<img class="elemental-silhouette" src="data:image/png;base64," alt="Silhueta de elemental">`;
}

function replaceBrokenSprite(img){
  const card = img ? img.closest('.variant-card') : null;
  const variant = card ? card.dataset.variant : '';

  const wrapper = document.createElement('div');
  wrapper.innerHTML = genericSilhouetteHtml().trim();
  const silhouette = wrapper.firstElementChild;
  if(img && img.parentNode && silhouette){
    img.parentNode.replaceChild(silhouette, img);
  }

  // A ausência da imagem não define disponibilidade. O card mantém o estado
  // configurado em isVariantSoon() e usa somente a silhueta como fallback.
}

const OFFICIAL_COLLECTION_TOTAL = 109;

function defaultRaridades(){
  return [
    {id:'r1', nome:'Comum', cor:'#9aa5b1'},
    {id:'r2', nome:'Incomum', cor:'#4fd672'},
    {id:'r3', nome:'Raro', cor:'#4c9fe8'},
    {id:'r4', nome:'Épico', cor:'#b45ce0'},
    {id:'r5', nome:'Lendário', cor:'#e8952f'},
    {id:'r6', nome:'Mítico', cor:'#f2c14e'},
  ];
}
function defaultVariantes(){
  return ['Normal','Dourado','Gelatinoso','Galáctico','Metalizado','Cúbico','Quack','Gema'];
}

function defaultTipos(){
  const FULL8 = defaultVariantes();
  const SO_NORMAL = ['Normal'];
  const mk = (nome, raridade, emoji, variantesDisponiveis) => ({
    id: crypto.randomUUID(), nome, raridade, emoji, slug: lookupSlug(nome),
    imagem: null, imagensVariantes: {}, variantes: {}, variantesDisponiveis
  });
  return [
    mk('Água','Raro','💧', FULL8),
    mk('Terra','Raro','🌍', FULL8),
    mk('Fogo','Raro','🔥', FULL8),
    mk('Ar','Raro','💨', FULL8),
    mk('Peixoto','Raro','🐟', FULL8),
    mk('Pato','Épico','🦆', FULL8),
    mk('Fantasma','Épico','👻', FULL8),
    mk('Demônio','Épico','😈', FULL8),
    mk('Rei','Épico','👑', FULL8),
    mk('Aura','Épico','✨', FULL8),
    mk('Atacante','Épico','⚽', FULL8),
    mk('Sonho','Lendário','💭', FULL8),
    mk('Punk','Lendário','🤘', FULL8),
    mk('Chefe','Lendário','🗿', FULL8),
    mk('Seven','Lendário','7️⃣', FULL8),
    mk('Ceifador','Mítico','💀', FULL8),
    mk('Ponto Zero','Mítico','🌀', FULL8),
    mk('Batman','Mítico','🦇', FULL8),
    mk('John Wick','Mítico','🕶️', SO_NORMAL),
    mk('Amendoim Torrado','Mítico','🥜', SO_NORMAL),
    mk('Pollo','Mítico','🐔', SO_NORMAL),
    mk('Vini Jr.','Mítico','🇧🇷', SO_NORMAL),
    mk('Ironmouse','Mítico','🎤', SO_NORMAL),
    // Lhama e Embananado entraram no jogo em 30/07 — raridade ainda não
    // confirmada oficialmente, ajuste pela ⚙ se a Epic definir diferente.
    mk('Lhama','Épico','🦙', FULL8),
    mk('Embananado','Épico','🍌', FULL8),
  ];
}

function loadLists(){
  try{
    const raw = localStorage.getItem(LISTS_KEY);
    if(!raw){ const d = {raridades: defaultRaridades(), variantes: defaultVariantes()}; saveLists(d); return d; }
    return JSON.parse(raw);
  }catch(e){ return {raridades: defaultRaridades(), variantes: defaultVariantes()}; }
}
function saveLists(l){ localStorage.setItem(LISTS_KEY, JSON.stringify(l)); }

function loadTipos(){
  try{
    const raw = localStorage.getItem(STORAGE_KEY);
    if(!raw){ const seed = defaultTipos(); saveTipos(seed); return seed; }
    return JSON.parse(raw);
  }catch(e){ return defaultTipos(); }
}
function saveTipos(t){ localStorage.setItem(STORAGE_KEY, JSON.stringify(t)); }

function applyVersionUpgrade(){
  const storedVersion = parseInt(localStorage.getItem(VERSION_KEY) || '0', 10);
  if(storedVersion >= DATA_VERSION) return;

  const newRaridades = defaultRaridades();
  const newVariantes = defaultVariantes();
  const newTiposSeed = defaultTipos();

  // Preserve progress: for each new-default tipo, if a tipo with the same
  // nome already exists locally, carry over its owned variantes/imagem.
  const existingByName = {};
  tipos.forEach(t => existingByName[t.nome] = t);
  const merged = newTiposSeed.map(nt => {
    const old = existingByName[nt.nome];
    if(old) return { ...nt, imagem: old.imagem || nt.imagem, imagensVariantes: { ...(old.imagensVariantes || {}) }, variantes: { ...old.variantes } };
    return nt;
  });
  // Keep any custom tipos the person added that aren't in the new defaults.
  const newNames = new Set(newTiposSeed.map(t => t.nome));
  tipos.forEach(t => { if(!newNames.has(t.nome)) merged.push(t); });

  tipos = merged;
  lists = { raridades: newRaridades, variantes: newVariantes };
  saveTipos(tipos);
  saveLists(lists);
  localStorage.setItem(VERSION_KEY, String(DATA_VERSION));
}

let lists = loadLists();
let tipos = loadTipos();
applyVersionUpgrade();
tipos.forEach(t => { if(!t.imagensVariantes) t.imagensVariantes = {}; });

async function loadRemoteCatalog(){
  try{
    const response = await fetch('./elementais.json', { cache: 'no-store' });
    if(!response.ok) throw new Error(`HTTP ${response.status}`);
    const catalog = await response.json();
    if(!catalog || !Array.isArray(catalog.tipos)) throw new Error('formato inválido');

    remoteCatalog = catalog;
    const existingBySlug = new Map(tipos.map(t => [t.slug, t]));
    const existingByName = new Map(tipos.map(t => [t.nome, t]));

    catalog.tipos.forEach((ct, index) => {
      let local = existingBySlug.get(ct.slug) || existingByName.get(ct.nome);
      const variantesDisponiveis = Array.isArray(ct.variantesDisponiveis)
        ? ct.variantesDisponiveis
        : Object.keys(ct.variantes || {});

      if(local){
        local.nome = ct.nome || local.nome;
        local.slug = ct.slug || local.slug;
        local.raridade = ct.raridade || local.raridade;
        local.emoji = ct.emoji || local.emoji;
        local.variantesDisponiveis = variantesDisponiveis.length
          ? variantesDisponiveis
          : local.variantesDisponiveis;
      } else {
        local = {
          id: crypto.randomUUID(),
          nome: ct.nome,
          slug: ct.slug,
          raridade: ct.raridade || 'Comum',
          emoji: ct.emoji || '❓',
          imagem: null,
          imagensVariantes: {},
          variantes: {},
          variantesDisponiveis
        };
        tipos.push(local);
      }
    });

    saveTipos(tipos);
  }catch(error){
    console.warn('Não foi possível carregar elementais.json; usando dados internos.', error);
  }
}


let filters = { tipo: 'all', variacao: 'all', status: 'all', search: '' };
let editingId = null;

function getRarityColor(nome){
  const r = lists.raridades.find(x => x.nome === nome);
  return r ? r.cor : FALLBACK_COLOR;
}
function nextColor(){
  const used = lists.raridades.map(r => r.cor);
  const free = COLOR_PALETTE.find(c => !used.includes(c));
  return free || COLOR_PALETTE[lists.raridades.length % COLOR_PALETTE.length];
}
function availableVariantes(t){
  const base = (t.variantesDisponiveis && t.variantesDisponiveis.length) ? t.variantesDisponiveis : lists.variantes;
  return base.filter(v => lists.variantes.includes(v));
}
function countableVariantes(t){
  return availableVariantes(t).filter(v => !isVariantSoon(t, v));
}

function getVariantState(t, variante){
  const value = t.variantes ? t.variantes[variante] : 0;
  if(value === true) return 1;
  if(value === false || value == null) return 0;
  const state = Number(value);
  return state === 2 ? 2 : (state === 1 ? 1 : 0);
}

function tipoOwnedCount(t){
  return countableVariantes(t).filter(v => getVariantState(t, v) > 0).length;
}

const STATUS_OPTIONS = [
  {v:'all', lbl:'Todos'},
  {v:'owned', lbl:'Conseguidos'},
  {v:'missing', lbl:'Faltando'},
  {v:'mastered', lbl:'Dominados'},
];

function buildFilterBars(){
  const tipoSelect = document.getElementById('tipoSelect');
  const variacaoSelect = document.getElementById('variacaoSelect');
  const statusWrap = document.getElementById('statusChips');

  const tipoNomes = [...new Set(tipos.map(t => t.nome))]
    .sort((a,b) => tipoOrderRank(a) - tipoOrderRank(b) || a.localeCompare(b,'pt-BR'));

  tipoSelect.innerHTML =
    `<option value="all">Todos os tipos</option>` +
    tipoNomes.map(n => `<option value="${n}">${n}</option>`).join('');
  tipoSelect.value = filters.tipo;
  tipoSelect.onchange = (e) => {
    filters.tipo = e.target.value;
    render();
  };

  variacaoSelect.innerHTML =
    `<option value="all">Todas as variações</option>` +
    lists.variantes.map(v => `<option value="${v}">${v}</option>`).join('');
  variacaoSelect.value = filters.variacao;
  variacaoSelect.onchange = (e) => {
    filters.variacao = e.target.value;
    render();
  };

  statusWrap.innerHTML = STATUS_OPTIONS.map(s =>
    `<div class="chip ${filters.status===s.v?'active':''}" data-s="${s.v}">${s.lbl}</div>`
  ).join('');
  statusWrap.querySelectorAll('.chip').forEach(c => c.onclick = () => {
    filters.status = c.dataset.s;
    render();
  });
}

document.getElementById('searchInput').addEventListener('input', (e) => {
  filters.search = e.target.value.trim().toLowerCase();
  render();
});

function matchesTipoFilter(t){
  if(filters.tipo !== 'all' && t.nome !== filters.tipo) return false;
  if(filters.search && !t.nome.toLowerCase().includes(filters.search)) return false;
  return true;
}

function visibleVariantesForTipo(t){
  let avail = availableVariantes(t);
  if(filters.variacao !== 'all') avail = avail.filter(v => v === filters.variacao);
  if(filters.status === 'owned') avail = avail.filter(v => !isVariantSoon(t,v) && getVariantState(t,v) > 0);
  if(filters.status === 'missing') avail = avail.filter(v => !isVariantSoon(t,v) && getVariantState(t,v) === 0);
  if(filters.status === 'mastered') avail = avail.filter(v => !isVariantSoon(t,v) && getVariantState(t,v) === 2);

  // Mantém as disponíveis primeiro e reúne todas as variações "Em breve" no final.
  return avail.sort((a,b) => Number(isVariantSoon(t,a)) - Number(isVariantSoon(t,b)));
}

function variantCardHtml(t, v){
  const color = getVariantColor(v);
  const soon = isVariantSoon(t, v);
  const state = soon ? 0 : getVariantState(t, v);
  const on = state > 0;
  const mastered = state === 2;
  const customVariantImage = t.imagensVariantes && t.imagensVariantes[v];
  const url = spriteUrl(t, v);
  let art;
  if(customVariantImage){
    art = `<img src="${customVariantImage}" alt="">`;
  } else if(t.imagem){
    art = `<img src="${t.imagem}" alt="">`;
  } else if(url){
    art = `<img src="${url}" alt="" loading="lazy" onerror="replaceBrokenSprite(this)">`;
  } else {
    art = genericSilhouetteHtml();
  }
  const safeVariant = v.replace(/'/g,"\\'");
  const click = soon ? '' : `onclick="toggleVariant('${t.id}','${safeVariant}')"`;
  return `
    <div class="variant-card ${on ? 'on' : ''} ${mastered ? 'mastered' : ''} ${soon ? 'soon' : ''}" data-variant="${v}" style="--variant-color:${color}" ${click}>
      <div class="variant-card-check">${mastered ? '👑' : '✓'}</div>
      ${soon ? '<div class="variant-card-soon">Em breve</div>' : ''}
      ${mastered ? '<div class="variant-card-mastered">Dominado</div>' : ''}
      <div class="variant-card-art">${art}</div>
      <div class="variant-card-name">${v}</div>
    </div>
  `;
}

function tipoGroupHtml(t){
  const color = getRarityColor(t.raridade);
  const avail = countableVariantes(t);
  const allAvail = availableVariantes(t);
  const soonCount = allAvail.filter(v => isVariantSoon(t, v)).length;
  const visible = visibleVariantesForTipo(t);
  const owned = tipoOwnedCount(t);
  const masteredCount = avail.filter(v => getVariantState(t, v) === 2).length;
  const masteredAll = avail.length > 0 && masteredCount === avail.length;
  const complete = avail.length > 0 && owned === avail.length;
  const partial = owned > 0 && !complete;
  const markerClass = masteredAll ? 'mastered' : (complete ? 'complete' : (partial ? 'partial' : ''));
  const markerText = masteredAll ? '👑' : (complete ? '✓' : (partial ? '•' : ''));
  const markerTitle = masteredAll
    ? `Todas as ${avail.length} variações disponíveis estão dominadas`
    : `${owned}/${avail.length} disponíveis desbloqueadas`;
  const thumb = t.imagem ? `<img src="${t.imagem}" alt="">` : (t.emoji || '❓');
  const cards = visible.map(v => variantCardHtml(t, v)).join('');
  const markLabel = complete ? 'Desmarcar todos' : 'Marcar todos';
  return `
    <div class="tipo-group">
      <div class="group-header">
        <div class="tipo-state-marker ${markerClass}" title="${markerTitle}">${markerText}</div>
        <div class="dot" style="background:${color}"></div>
        <div class="tipo-group-thumb">${thumb}</div>
        <div class="name">${t.nome}</div>
        <div class="count">${owned}/${allAvail.length}</div>
        ${soonCount ? `<div class="tipo-soon-count">(${soonCount} em breve)</div>` : ''}
        <button class="tipo-mark-all" onclick="markAllTipo('${t.id}')">${markLabel}</button>
      </div>
      <div class="variant-card-grid">${cards}</div>
    </div>
  `;
}

function render(){
  buildFilterBars();
  const content = document.getElementById('content');

  const raridadeRank = {};
  lists.raridades.forEach((r,i) => raridadeRank[r.nome] = i);
  const filtered = tipos.filter(matchesTipoFilter)
    .filter(t => visibleVariantesForTipo(t).length > 0)
    .sort((a,b) => {
      const oa = tipoOrderRank(a.nome), ob = tipoOrderRank(b.nome);
      if(oa !== ob) return oa - ob;
      return a.nome.localeCompare(b.nome, 'pt-BR');
    });

  let ownedTotal = 0, availableTotal = 0, soonTotal = 0;
  tipos.forEach(t => {
    ownedTotal += tipoOwnedCount(t);
    availableTotal += countableVariantes(t).length;
    soonTotal += availableVariantes(t).filter(v => isVariantSoon(t, v)).length;
  });
  document.getElementById('availableCount').textContent = availableTotal;
  document.getElementById('unlockedCount').textContent = ownedTotal;
  document.getElementById('totalCount').textContent = soonTotal;
  document.getElementById('progressFill').style.width = availableTotal ? (ownedTotal/availableTotal*100)+'%' : '0%';

  if(filtered.length === 0){
    content.innerHTML = '<div class="empty-msg">Nenhum elemental encontrado com esses filtros.</div>';
    return;
  }

  content.innerHTML = filtered.map(tipoGroupHtml).join('');
}

function markAllTipo(tipoId){
  const t = tipos.find(x => x.id === tipoId);
  if(!t) return;

  const disponiveis = countableVariantes(t);
  const todosMarcados = disponiveis.length > 0 && disponiveis.every(v => getVariantState(t, v) > 0);

  disponiveis.forEach(v => {
    t.variantes[v] = todosMarcados ? 0 : 1;
  });

  saveTipos(tipos);
  if(navigator.vibrate) navigator.vibrate(20);
  render();
}

function toggleVariant(tipoId, variante){
  const t = tipos.find(x => x.id === tipoId);
  if(!t || isVariantSoon(t, variante)) return;

  const currentState = getVariantState(t, variante);
  t.variantes[variante] = currentState === 0 ? 1 : (currentState === 1 ? 2 : 0);

  saveTipos(tipos);
  if(navigator.vibrate) navigator.vibrate(t.variantes[variante] === 2 ? [20,35,20] : 15);
  render();
}

/* ---------- Foto individual por variação ---------- */
let pendingVariantImageTarget = null;

function chooseVariantImage(tipoId, variante){
  pendingVariantImageTarget = { tipoId, variante };
  const input = document.getElementById('variantImageInput');
  input.value = '';
  input.click();
}

document.getElementById('variantImageInput').addEventListener('change', (e) => {
  const file = e.target.files[0];
  if(!file || !pendingVariantImageTarget) return;

  const reader = new FileReader();
  reader.onload = (ev) => {
    const img = new Image();
    img.onload = () => {
      const maxW = 360;
      const scale = Math.min(1, maxW / img.width);
      const canvas = document.createElement('canvas');
      canvas.width = Math.round(img.width * scale);
      canvas.height = Math.round(img.height * scale);
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

      const t = tipos.find(x => x.id === pendingVariantImageTarget.tipoId);
      if(!t) return;
      t.imagensVariantes = t.imagensVariantes || {};
      t.imagensVariantes[pendingVariantImageTarget.variante] = canvas.toDataURL('image/jpeg', 0.78);
      saveTipos(tipos);
      pendingVariantImageTarget = null;
      render();
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
});

/* ---------- Modal (novo/editar tipo) ---------- */
let pendingImage = null;
let pendingVariantesDisponiveis = [];

function openModal(id){
  editingId = id || null;
  const overlay = document.getElementById('overlay');
  const t = id ? tipos.find(x => x.id === id) : null;
  pendingImage = t ? t.imagem : null;
  pendingVariantesDisponiveis = t ? [...availableVariantes(t)] : [...lists.variantes];

  document.getElementById('modalTitle').textContent = t ? 'Editar tipo' : 'Novo tipo de elemental';
  document.getElementById('fNome').value = t ? t.nome : '';

  const raridadeSel = document.getElementById('fRaridade');
  raridadeSel.innerHTML = lists.raridades.map(r => `<option value="${r.nome}">${r.nome}</option>`).join('');
  raridadeSel.value = t ? t.raridade : (lists.raridades[0] ? lists.raridades[0].nome : '');

  document.getElementById('btnDelete').style.display = t ? 'block' : 'none';

  updateImgPreview();
  buildEmojiPicker(t ? t.emoji : '🧩');
  buildModalVariantesDisponiveis();

  overlay.classList.add('show');
}
function closeModal(){
  document.getElementById('overlay').classList.remove('show');
  editingId = null;
  pendingImage = null;
  pendingVariantesDisponiveis = [];
}
document.getElementById('overlay').addEventListener('click', (e) => {
  if(e.target.id === 'overlay') closeModal();
});

function buildModalVariantesDisponiveis(){
  const wrap = document.getElementById('modalVariants');
  wrap.innerHTML = lists.variantes.map(v => `
    <div class="modal-variant-row">
      <span>${v}</span>
      <div class="mini-switch ${pendingVariantesDisponiveis.includes(v) ? 'on' : ''}" onclick="toggleModalVariante(this,'${v.replace(/'/g,"\\'")}')"></div>
    </div>
  `).join('');
}
function toggleModalVariante(el, v){
  el.classList.toggle('on');
  if(el.classList.contains('on')){
    if(!pendingVariantesDisponiveis.includes(v)) pendingVariantesDisponiveis.push(v);
  } else {
    pendingVariantesDisponiveis = pendingVariantesDisponiveis.filter(x => x !== v);
  }
}

function buildEmojiPicker(selected){
  const picker = document.getElementById('emojiPicker');
  picker.innerHTML = EMOJI_OPTIONS.map(em =>
    `<div class="emoji-opt ${em === selected ? 'sel' : ''}" data-e="${em}">${em}</div>`
  ).join('');
  picker.dataset.selected = selected || '🧩';
  picker.querySelectorAll('.emoji-opt').forEach(el => el.onclick = () => {
    picker.querySelectorAll('.emoji-opt').forEach(x => x.classList.remove('sel'));
    el.classList.add('sel');
    picker.dataset.selected = el.dataset.e;
  });
}

function updateImgPreview(){
  const prev = document.getElementById('imgPreview');
  prev.innerHTML = pendingImage ? `<img src="${pendingImage}">` : '🧩';
}
function clearImage(){ pendingImage = null; updateImgPreview(); }

document.getElementById('fImagem').addEventListener('change', (e) => {
  const file = e.target.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = (ev) => {
    const img = new Image();
    img.onload = () => {
      const maxW = 240;
      const scale = Math.min(1, maxW / img.width);
      const canvas = document.createElement('canvas');
      canvas.width = img.width * scale;
      canvas.height = img.height * scale;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      pendingImage = canvas.toDataURL('image/jpeg', 0.72);
      updateImgPreview();
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
});

function saveCurrent(){
  const nome = document.getElementById('fNome').value.trim();
  if(!nome){ alert('Dá um nome pro tipo!'); return; }
  if(pendingVariantesDisponiveis.length === 0){ alert('Marca pelo menos uma variação pra esse tipo!'); return; }
  const raridade = document.getElementById('fRaridade').value;
  const emoji = document.getElementById('emojiPicker').dataset.selected || '🧩';

  if(editingId){
    const t = tipos.find(x => x.id === editingId);
    t.nome = nome; t.raridade = raridade; t.emoji = emoji; t.imagem = pendingImage;
    t.imagensVariantes = t.imagensVariantes || {};
    t.slug = t.slug || lookupSlug(nome);
    t.variantesDisponiveis = [...pendingVariantesDisponiveis];
  } else {
    tipos.push({
      id: crypto.randomUUID(), nome, raridade, emoji, slug: lookupSlug(nome),
      imagem: pendingImage, imagensVariantes: {}, variantes: {}, variantesDisponiveis: [...pendingVariantesDisponiveis]
    });
  }
  saveTipos(tipos);
  closeModal();
  render();
}

function deleteCurrent(){
  if(!editingId) return;
  if(!confirm('Excluir este tipo (e o progresso dele) da sua lista?')) return;
  tipos = tipos.filter(t => t.id !== editingId);
  saveTipos(tipos);
  closeModal();
  render();
}

/* ---------- Backup ---------- */
function exportData(){
  const blob = new Blob([JSON.stringify({ tipos, lists }, null, 2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'meus-elementais-backup.json';
  a.click();
  URL.revokeObjectURL(url);
}
document.getElementById('importFile').addEventListener('change', (e) => {
  const file = e.target.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = (ev) => {
    try{
      const data = JSON.parse(ev.target.result);
      if(!data.tipos || !data.lists) throw new Error('formato inválido');
      tipos = data.tipos; lists = data.lists;
      saveTipos(tipos); saveLists(lists);
      render();
      alert('Backup importado!');
    }catch(err){ alert('Arquivo inválido.'); }
  };
  reader.readAsText(file);
  e.target.value = '';
});

function resetAll(){
  if(!confirm('Isso vai apagar TODOS os seus elementais salvos e voltar à lista inicial. Continuar?')) return;
  tipos = defaultTipos();
  lists = { raridades: defaultRaridades(), variantes: defaultVariantes() };
  saveTipos(tipos); saveLists(lists);
  render();
}

/* ---------- List manager (tipo / variação / raridade) ---------- */
function openListManager(){
  renderListManager();
  document.getElementById('listOverlay').classList.add('show');
}
function closeListManager(){
  document.getElementById('listOverlay').classList.remove('show');
  render();
}
document.getElementById('listOverlay').addEventListener('click', (e) => {
  if(e.target.id === 'listOverlay') closeListManager();
});

function renderListManager(){
  const tipoRows = document.getElementById('tipoListRows');
  tipoRows.innerHTML = [...tipos].sort((a,b)=>a.nome.localeCompare(b.nome,'pt-BR')).map(t => `
    <div class="list-row" onclick="editTipoFromList('${t.id}')">
      <div class="swatch" style="background:${getRarityColor(t.raridade)}">${t.imagem ? '' : (t.emoji||'')}</div>
      <div class="lbl">${t.nome}</div>
      <button class="del" onclick="event.stopPropagation(); removeTipoFromList('${t.id}')">×</button>
    </div>
  `).join('') || '<div class="list-hint">Nenhum tipo cadastrado.</div>';

  const raridadeRows = document.getElementById('raridadeListRows');
  raridadeRows.innerHTML = lists.raridades.map(r => `
    <div class="list-row no-click">
      <div class="swatch" style="background:${r.cor}"></div>
      <div class="lbl">${r.nome}</div>
      <button class="del" onclick="removeListEntry('raridades','${r.id}')">×</button>
    </div>
  `).join('') || '<div class="list-hint">Nenhuma raridade cadastrada.</div>';

  const variantRows = document.getElementById('variantListRows');
  variantRows.innerHTML = lists.variantes.map(v => `
    <div class="list-row no-click">
      <div class="lbl">${v}</div>
      <button class="del" onclick="removeListEntry('variantes','${v}')">×</button>
    </div>
  `).join('') || '<div class="list-hint">Nenhuma variação cadastrada.</div>';
}

function editTipoFromList(id){
  closeListManager();
  openModal(id);
}

function removeTipoFromList(id){
  const t = tipos.find(x => x.id === id);
  if(!t) return;
  if(!confirm(`Excluir "${t.nome}" e o progresso dele da sua lista?`)) return;
  tipos = tipos.filter(x => x.id !== id);
  saveTipos(tipos);
  renderListManager();
}

function addListEntry(type){
  if(type === 'tipos'){
    const input = document.getElementById('newTipoInput');
    const nome = input.value.trim();
    if(!nome) return;
    if(tipos.some(x => x.nome.toLowerCase() === nome.toLowerCase())){ alert('Já existe um tipo com esse nome.'); return; }
    tipos.push({
      id: crypto.randomUUID(), nome,
      raridade: lists.raridades[0] ? lists.raridades[0].nome : '',
      emoji: '🧩', slug: lookupSlug(nome), imagem: null, imagensVariantes: {},
      variantes: {}, variantesDisponiveis: [...lists.variantes]
    });
    saveTipos(tipos);
    input.value = '';
  } else if(type === 'raridades'){
    const input = document.getElementById('newRaridadeInput');
    const nome = input.value.trim();
    if(!nome) return;
    if(lists.raridades.some(x => x.nome.toLowerCase() === nome.toLowerCase())){ alert('Já existe uma raridade com esse nome.'); return; }
    lists.raridades.push({ id: crypto.randomUUID(), nome, cor: nextColor() });
    saveLists(lists);
    input.value = '';
  } else {
    const input = document.getElementById('newVariantInput');
    const nome = input.value.trim();
    if(!nome) return;
    if(lists.variantes.some(x => x.toLowerCase() === nome.toLowerCase())){ alert('Já existe uma variação com esse nome.'); return; }
    lists.variantes.push(nome);
    saveLists(lists);
    input.value = '';
  }
  renderListManager();
}

function removeListEntry(type, key){
  if(type === 'raridades'){
    if(lists.raridades.length <= 1){ alert('Precisa manter pelo menos uma raridade.'); return; }
    const entry = lists.raridades.find(x => x.id === key);
    const inUse = tipos.filter(t => t.raridade === entry.nome).length;
    const msg = inUse
      ? `${inUse} tipo(s) usam "${entry.nome}". Remover não apaga esses tipos, só some das opções pra novos cadastros. Continuar?`
      : `Remover "${entry.nome}" da lista?`;
    if(!confirm(msg)) return;
    lists.raridades = lists.raridades.filter(x => x.id !== key);
  } else {
    if(lists.variantes.length <= 1){ alert('Precisa manter pelo menos uma variação.'); return; }
    const inUse = tipos.filter(t => t.variantes[key]).length;
    const msg = inUse
      ? `${inUse} tipo(s) têm "${key}" marcado. Remover não apaga isso, só some do card pra todo mundo. Continuar?`
      : `Remover "${key}" da lista?`;
    if(!confirm(msg)) return;
    lists.variantes = lists.variantes.filter(x => x !== key);
  }
  saveLists(lists);
  renderListManager();
}

async function bootstrap(){
  await loadRemoteCatalog();
  render();
}
bootstrap();
